<?php
require_once __DIR__ . '/_common.php';$pageTitle='Log aktivitas';$path=storage_path('logs/osis/aktivitas.log');$entries=[];if(is_file($path)){$lines=@file($path,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES);if($lines){foreach(array_slice(array_reverse($lines),0,150) as $line){$item=json_decode($line,true);if(is_array($item))$entries[]=$item;}}}osis_admin_page_start($pageTitle);
?>
<div class="admin-page-actions"><p>Riwayat perubahan aplikasi tersimpan di file lokal, bukan di tabel database.</p><span class="result-count"><?=count($entries)?> aktivitas terbaru</span></div><div class="admin-panel"><div class="admin-activity-list log-list"><?php if($entries):foreach($entries as $entry):?><div class="admin-activity-row"><span class="activity-icon">◴</span><span class="activity-copy"><strong><?=osis_e((isset($entry['aktivitas'])?$entry['aktivitas']:'Aktivitas'))?></strong><small><?=osis_e((isset($entry['pengguna'])?$entry['pengguna']:'Sistem'))?> · <?=osis_e(strtoupper((isset($entry['peran'])?$entry['peran']:'')))?></small></span><time><?=osis_e(osis_format_date((isset($entry['waktu'])?$entry['waktu']:''),true))?></time></div><?php endforeach;else:?><div class="empty-inline">Belum ada aktivitas tercatat.</div><?php endif;?></div></div>
<?php osis_admin_page_end(); ?>
